package com.example.starter.deicing.domain;

/**
 * 除冰工艺类型。
 */
public enum DeicingType {

    /**
     * 一步法除冰：单次作业，无防冰液保持时间（HOT）约束。
     */
    ONE_STEP,

    /**
     * 两步法除冰：先除冰后施加防冰液，须在 HOT 内完成起飞。
     */
    TWO_STEP
}

package com.example.starter.deicing.domain;

/**
 * 除冰排队记录状态。
 */
public enum RequestStatus {

    /** 已受理，等待出队。 */
    QUEUED,

    /** 已出队确认，车位与作业窗口已排定。 */
    SCHEDULED,

    /** 除冰作业开始（车位不可再被抢占）。 */
    IN_PROGRESS,

    /** 前序延误导致无法按计划满足起飞/HOT 约束，等待航班重排起飞时刻。 */
    HOT_RISK,

    /** 终态：已起飞。 */
    TAKEN_OFF,

    /** 终态：已取消。 */
    CANCELLED,

    /** 终态：实际起飞时 HOT 已超时，除冰失效，需重新除冰。 */
    HOT_EXPIRED
}

package com.example.starter.deicing.service;

/**
 * HOT 风险的具体成因，用于接口提示。
 */
public enum HotRiskReason {

    /** 车位被前序作业占用，最早可完成时刻已晚于计划起飞时刻。 */
    LATE_COMPLETION,

    /** 两步法防冰液在计划起飞时刻前失效，且起飞时刻前无可用重排窗口。 */
    HOT_EXPIRY_RISK
}

package com.example.starter.deicing.web;

import org.springframework.http.HttpStatus;

/**
 * 业务可预期错误，携带 HTTP 状态码与提示信息。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }

    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, message);
    }
}

