package com.example.starter.deicing.web.dto;

import java.util.List;

/**
 * 申请/出队/作业等写操作的统一响应。
 *
 * @param replay 是否为幂等重放（返回首次结果）
 * @param bays   出队后实际分配的车位编号列表
 */
public record MutationResponse(
        QueueItemView item,
        boolean replay,
        List<String> bays) {

    public static MutationResponse of(QueueItemView item, boolean replay, List<String> bays) {
        return new MutationResponse(item, replay, bays == null ? List.of() : List.copyOf(bays));
    }
}

package com.example.starter.deicing.web.dto;

import java.time.Instant;
import java.util.List;

/**
 * 起飞回报结果。
 *
 * @param valid true=HOT 有效（已起飞终态）；false=HOT 超时失效，需重新除冰
 * @param replay 是否为终态幂等重放
 */
public record TakeoffResponse(
        QueueItemView item,
        boolean valid,
        boolean replay,
        Instant hotDeadline) {

    public static List<String> noBays() {
        return List.of();
    }
}

package com.example.starter.deicing.web.dto;

import java.time.Instant;
import java.util.List;

/**
 * 队列快照，按调度优先级排序，重复查询结果稳定。
 */
public record SnapshotResponse(Instant generatedAt, List<QueueItemView> items) {
}

package com.example.starter.deicing.web.dto;

import java.time.Instant;
import java.util.List;

/**
 * 单个车位的占用时间线（半开区间 [start, end)）。
 */
public record BayTimelineView(String bayCode, List<OccupancyView> occupancies) {

    /**
     * 车位占用区间。
     */
    public record OccupancyView(
            String requestId,
            String flightNumber,
            Instant start,
            Instant end,
            String status) {
    }
}

package com.example.starter.deicing.web.dto;

import java.time.Instant;
import java.util.List;

/**
 * 全部车位占用时间线响应。
 */
public record TimelineResponse(Instant generatedAt, List<BayTimelineView> bays) {
}

package com.example.starter.deicing.web.dto;

/**
 * 统一错误响应。
 */
public record ErrorResponse(String error, String message) {
}

