package com.example.starter.deicing.service;

import com.example.starter.deicing.db.DeicingAllocationPo;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.stereotype.Component;

/**
 * 车位半开区间 [start, end) 调度计算：端点相接不冲突，内部重叠冲突。
 */
@Component
public class SchedulingCalculator {

    /**
     * 单个车位上的一段可放置窗口。
     */
    public record BayWindow(String bayCode, Instant windowStart, Instant windowEnd) {

        /** 窗口内能否容纳 duration 长度的作业。 */
        public boolean fits(java.time.Duration duration) {
            return !windowStart.plus(duration).isAfter(windowEnd);
        }
    }

    /**
     * 多个车位同步可用的组合窗口。
     */
    public record CombinedWindow(Instant start, Instant end, List<String> bayCodes) {
    }

    /**
     * 计算某车位在 earliest 之后可容纳 duration 作业的全部空闲窗口（半开区间）。
     */
    public List<BayWindow> freeWindows(String bayCode, Instant earliest,
                                       java.time.Duration duration,
                                       List<DeicingAllocationPo> occupied) {
        List<DeicingAllocationPo> sorted = occupied.stream()
                .filter(a -> a.getBayCode().equals(bayCode))
                .filter(a -> a.getEndTime().isAfter(earliest))
                .sorted(Comparator.comparing(DeicingAllocationPo::getStartTime)
                        .thenComparing(DeicingAllocationPo::getEndTime))
                .toList();

        List<BayWindow> windows = new ArrayList<>();
        Instant cursor = earliest;
        for (DeicingAllocationPo o : sorted) {
            if (!o.getStartTime().isAfter(cursor)) {
                // 区间覆盖或相接：推进游标（相接时取较晚结束点）
                if (o.getEndTime().isAfter(cursor)) {
                    cursor = o.getEndTime();
                }
                continue;
            }
            windows.add(new BayWindow(bayCode, cursor, o.getStartTime()));
            cursor = o.getEndTime();
        }
        windows.add(new BayWindow(bayCode, cursor, Instant.MAX));
        return windows.stream().filter(w -> w.fits(duration)).toList();
    }

    /**
     * 在给定车位集合中，寻找 earliest 之后能让 requiredBays 个车位同时空闲、
     * 且开始时刻最早的组合窗口。开始时刻相同时取结束更晚、车位编号更小的组合。
     */
    public CombinedWindow earliestCombinedWindow(List<String> bayCodes, Instant earliest,
                                                 java.time.Duration duration,
                                                 List<DeicingAllocationPo> occupied) {
        // 每个车位的空闲边界点；组合窗口起点一定是某个车位的空闲起点
        TreeMap<Instant, List<String>> startIndex = new TreeMap<>();
        Map<String, List<BayWindow>> windowsByBay = new TreeMap<>();
        for (String bay : bayCodes) {
            List<BayWindow> windows = freeWindows(bay, earliest, duration, occupied);
            windowsByBay.put(bay, windows);
            for (BayWindow w : windows) {
                startIndex.computeIfAbsent(w.windowStart(), k -> new ArrayList<>()).add(bay);
            }
        }

        CombinedWindow best = null;
        for (Map.Entry<Instant, List<String>> entry : startIndex.entrySet()) {
            Instant candidateStart = entry.getKey();
            if (best != null && !candidateStart.equals(best.start())) {
                break; // 后续起点严格更晚，无需再看
            }
            List<String> available = new ArrayList<>();
            Instant commonEnd = Instant.MAX;
            for (Map.Entry<String, List<BayWindow>> bayEntry : windowsByBay.entrySet()) {
                BayWindow covering = bayEntry.getValue().stream()
                        .filter(w -> !candidateStart.isBefore(w.windowStart())
                                && !candidateStart.plus(duration).isAfter(w.windowEnd()))
                        .findFirst().orElse(null);
                if (covering != null) {
                    available.add(bayEntry.getKey());
                    if (covering.windowEnd().isBefore(commonEnd)) {
                        commonEnd = covering.windowEnd();
                    }
                }
            }
            if (available.size() >= bayCodes.size()) {
                CombinedWindow candidate = new CombinedWindow(candidateStart, commonEnd,
                        available.subList(0, bayCodes.size()));
                if (best == null || candidate.end.isAfter(best.end())) {
                    best = candidate;
                }
            }
        }
        return best;
    }

    /**
     * 队列优先级比较：先按截止时刻（起飞时刻减除冰时长）升序，截止相同按申请序号升序。
     */
    public static Comparator<QueuePrioritizable> priorityComparator() {
        return Comparator.comparing(QueuePrioritizable::deadline)
                .thenComparingLong(QueuePrioritizable::seq);
    }

    /**
     * 可参与队列排序的最小数据视图。
     */
    public interface QueuePrioritizable {

        Instant deadline();

        long seq();
    }
}

