1	package com.example.starter.deicing.service;
2	
3	import com.example.starter.deicing.db.AllocationRepository;
4	import com.example.starter.deicing.db.BayRepository;
5	import com.example.starter.deicing.db.DeicingAllocationPo;
6	import com.example.starter.deicing.db.DeicingBayPo;
7	import com.example.starter.deicing.db.DeicingRequestPo;
8	import com.example.starter.deicing.db.LatchRepository;
9	import com.example.starter.deicing.db.RequestRepository;
10	import com.example.starter.deicing.db.TimetableRepository;
11	import com.example.starter.deicing.domain.DeicingType;
12	import com.example.starter.deicing.domain.RequestStatus;
13	import com.example.starter.deicing.web.ApiException;
14	import com.example.starter.deicing.web.dto.ApplicationRequest;
15	import com.example.starter.deicing.web.dto.BayTimelineView;
16	import com.example.starter.deicing.web.dto.MutationResponse;
17	import com.example.starter.deicing.web.dto.QueueItemView;
18	import com.example.starter.deicing.web.dto.SnapshotResponse;
19	import com.example.starter.deicing.web.dto.TakeoffResponse;
20	import com.example.starter.deicing.web.dto.TimelineResponse;
21	import java.time.Duration;
22	import java.time.Instant;
23	import java.util.ArrayList;
24	import java.util.Comparator;
25	import java.util.LinkedHashMap;
26	import java.util.List;
27	import java.util.Map;
28	import org.springframework.dao.DuplicateKeyException;
29	import org.springframework.stereotype.Service;
30	import org.springframework.transaction.annotation.Transactional;
31	
32	/**
33	 * 除冰排队核心服务：申请幂等、先申请先服务/截止优先出队、半开区间车位分配、
34	 * 两步法 HOT 判定与终态幂等。
35	 */
36	@Service
37	public class DeicingService {
38	
39	    private final RequestRepository requestRepository;
40	    private final AllocationRepository allocationRepository;
41	    private final BayRepository bayRepository;
42	    private final TimetableRepository timetableRepository;
43	    private final LatchRepository latchRepository;
44	    private final SchedulingCalculator calculator;
45	    private final ViewMapper viewMapper;
46	    private final TimeSource timeSource;
47	
48	    public DeicingService(RequestRepository requestRepository,
49	                          AllocationRepository allocationRepository,
50	                          BayRepository bayRepository,
51	                          TimetableRepository timetableRepository,
52	                          LatchRepository latchRepository,
53	                          SchedulingCalculator calculator,
54	                          ViewMapper viewMapper,
55	                          TimeSource timeSource) {
56	        this.requestRepository = requestRepository;
57	        this.allocationRepository = allocationRepository;
58	        this.bayRepository = bayRepository;
59	        this.timetableRepository = timetableRepository;
60	        this.latchRepository = latchRepository;
61	        this.calculator = calculator;
62	        this.viewMapper = viewMapper;
63	        this.timeSource = timeSource;
64	    }
65	
66	    /**
67	     * 除冰申请。requestId 幂等：同键同参返回首次结果，同键异参 409；
68	     * 同一航班仅允许一条进行中记录，并发申请由行锁 + 唯一约束唯一受理。
69	     */
70	    @Transactional
71	    public MutationResponse apply(ApplicationRequest request) {
72	        Instant now = timeSource.now();
73	        if (!request.targetTakeoffTime().isAfter(now)) {
74	            throw ApiException.badRequest("目标起飞时刻必须晚于当前时刻");
75	        }
76	        Instant requestDeadline = request.targetTakeoffTime()
77	                .minusSeconds(request.durationMinutes() * 60L);
78	        if (requestDeadline.isBefore(now)) {
79	            throw ApiException.badRequest("截止时刻（起飞时刻减除冰时长）已过");
80	        }
81	
82	        String fingerprint = Fingerprints.sha256(request.requestId(), request.flightNumber(),
83	                request.standCode(), request.type(), request.requiredBays(),
84	                request.durationMinutes(), request.targetTakeoffTime());
85	
86	        DeicingRequestPo existing = requestRepository.findByRequestId(request.requestId());
87	        if (existing != null) {
88	            return replayOrConflict(existing, fingerprint);
89	        }
90	
91	        Integer hotMinutes = resolveHot(request.type(), request.flightNumber());
92	
93	        try {
94	            // 航班闩锁串行化同一航班的并发申请
95	            latchRepository.lockFlight(request.flightNumber());
96	            existing = requestRepository.findByRequestId(request.requestId());
97	            if (existing != null) {
98	                return replayOrConflict(existing, fingerprint);
99	            }
100	            if (requestRepository.countActiveByFlight(request.flightNumber()) > 0) {
101	                throw ApiException.conflict("航班 " + request.flightNumber() + " 已存在进行中的除冰队列记录");
102	            }
103	            int activeBays = bayRepository.findActive().size();
104	            if (request.requiredBays() > activeBays) {
105	                throw ApiException.badRequest("所需车位数 " + request.requiredBays()
106	                        + " 超过可用车位数 " + activeBays);
107	            }
108	
109	            DeicingRequestPo po = new DeicingRequestPo();
110	            po.setRequestId(request.requestId());
111	            po.setFlightNumber(request.flightNumber());
112	            po.setStandCode(request.standCode());
113	            po.setType(request.type());
114	            po.setRequiredBays(request.requiredBays());
115	            po.setDurationMinutes(request.durationMinutes());
116	            po.setTargetTakeoffTime(request.targetTakeoffTime());
117	            po.setDeadline(request.targetTakeoffTime().minusSeconds(request.durationMinutes() * 60L));
118	            po.setStatus(RequestStatus.QUEUED);
119	            po.setHotMinutes(hotMinutes);
120	            po.setFingerprint(fingerprint);
121	            po.setCreatedAt(now);
122	            po.setUpdatedAt(now);
123	            requestRepository.insert(po);
124	            DeicingRequestPo stored = requestRepository.findByRequestId(request.requestId());
125	            return MutationResponse.of(viewMapper.toView(stored), false, List.of());
126	        } catch (DuplicateKeyException e) {
127	            DeicingRequestPo raced = requestRepository.findByRequestId(request.requestId());
128	            if (raced != null) {
129	                return replayOrConflict(raced, fingerprint);
130	            }
131	            throw e;
132	        }
133	    }
134	
135	    /**
136	     * 出队确认：仅队首（截止时刻最早、同刻按申请序号）可出队，禁止插队。
137	     * 排定成功返回车位与作业窗口；无法在截止前满足 HOT/时长时置 HOT_RISK，
138	     * 给出最早可重排时刻，不静默放行。
139	     */
140	    @Transactional
141	    public MutationResponse dequeue(String requestId) {
142	        DeicingRequestPo po = mustFind(requestId);
143	        if (po.getStatus() != RequestStatus.QUEUED && po.getStatus() != RequestStatus.HOT_RISK) {
144	            return mutationReplay(po);
145	        }
146	
147	        // 全局调度闩锁：所有出队分配串行化，杜绝并发双分配
148	        latchRepository.lockSchedule();
149	
150	        List<DeicingRequestPo> queued = requestRepository.findAll().stream()
151	                .filter(r -> r.getStatus() == RequestStatus.QUEUED)
152	                .sorted(Comparator.comparing(DeicingRequestPo::getDeadline)
153	                        .thenComparingLong(DeicingRequestPo::getSeq))
154	                .toList();
155	        DeicingRequestPo head;
156	        if (po.getStatus() == RequestStatus.HOT_RISK) {
157	            head = po; // HOT_RISK 重新出队不参与普通队首比较
158	        } else {
159	            head = queued.isEmpty() ? po : queued.get(0);
160	            if (!head.getRequestId().equals(requestId)) {
161	                throw ApiException.conflict("申请 " + requestId + " 不在队首，当前队首为 "
162	                        + head.getRequestId() + "，禁止插队");
163	            }
164	        }
165	
166	        return schedule(head);
167	    }
168	
169	    private MutationResponse schedule(DeicingRequestPo po) {
170	        Instant now = timeSource.now();
171	        Duration duration = Duration.ofMinutes(po.getDurationMinutes());
172	        Instant deadline = po.getTargetTakeoffTime().minus(duration);
173	
174	        List<String> activeBays = bayRepository.findActive().stream()
175	                .map(DeicingBayPo::getBayCode).toList();
176	        List<DeicingAllocationPo> occupied = allocationRepository.findAll().stream()
177	                .filter(a -> a.getEndTime().isAfter(now)).toList();
178	
179	        // TWO_STEP：作业完成时刻须不早于 target-HOT，保证恰在 HOT 终点起飞仍有效
180	        Instant bandLower = now;
181	        if (po.getType() == DeicingType.TWO_STEP && po.getHotMinutes() != null) {
182	            Instant hotBound = po.getTargetTakeoffTime()
183	                    .minusSeconds(po.getHotMinutes() * 60L).minus(duration);
184	            if (hotBound.isAfter(bandLower)) {
185	                bandLower = hotBound;
186	            }
187	        }
188	
189	        BaySelection selection = selectBays(activeBays, bandLower, duration, occupied,
190	                po.getRequiredBays());
191	
192	        Instant now2 = timeSource.now();
193	        if (selection != null && !selection.start.isAfter(deadline)) {
194	            Instant start = selection.start;
195	            Instant end = start.plus(duration);
196	            // 数据库边界复核：半开 [start,end) 内部重叠才冲突，端点相接不冲突
197	            List<DeicingAllocationPo> clashes = allocationRepository.findOverlapping(
198	                    selection.bays, start, end);
199	            if (!clashes.isEmpty()) {
200	                throw ApiException.conflict("车位在 [" + start + ", " + end
201	                        + ") 已被占用，分配冲突");
202	            }
203	            for (String bay : selection.bays) {
204	                DeicingAllocationPo allocation = new DeicingAllocationPo();
205	                allocation.setRequestId(po.getRequestId());
206	                allocation.setFlightNumber(po.getFlightNumber());
207	                allocation.setBayCode(bay);
208	                allocation.setStartTime(start);
209	                allocation.setEndTime(end);
210	                allocation.setStatus(RequestStatus.SCHEDULED.name());
211	                allocation.setCreatedAt(now2);
212	                allocationRepository.insert(allocation);
213	            }
214	            po.setStatus(RequestStatus.SCHEDULED);
215	            po.setScheduledStart(start);
216	            po.setScheduledEnd(end);
217	            po.setHotRiskReason(null);
218	            po.setEarliestReassignTime(null);
219	            po.setUpdatedAt(now2);
220	            requestRepository.updateSchedule(po);
221	            DeicingRequestPo stored = requestRepository.findByRequestId(po.getRequestId());
222	            return MutationResponse.of(viewMapper.toView(stored), false, selection.bays);
223	        }
224	
225	        // 无法在截止前满足：置 HOT 风险，给出最早可重排（最早可重新开始作业）时刻
226	        BaySelection earliest = selectBays(activeBays, now, duration, occupied,
227	                po.getRequiredBays());
228	        Instant earliestStart = earliest == null ? now : earliest.start;
229	        HotRiskReason reason = earliestStart.plus(duration).isAfter(po.getTargetTakeoffTime())
230	                ? HotRiskReason.LATE_COMPLETION
231	                : HotRiskReason.HOT_EXPIRY_RISK;
232	        po.setStatus(RequestStatus.HOT_RISK);
233	        po.setHotRiskReason(reason.name());
234	        po.setEarliestReassignTime(earliestStart);
235	        po.setUpdatedAt(now2);
236	        requestRepository.updateSchedule(po);
237	        DeicingRequestPo stored = requestRepository.findByRequestId(po.getRequestId());
238	        return MutationResponse.of(viewMapper.toView(stored), false, List.of());
239	    }
240	
241	    /**
242	     * 作业开始：仅 SCHEDULED 可触发，开始后车位占用保留，不可被插队。
243	     */
244	    @Transactional
245	    public MutationResponse startJob(String requestId) {
246	        DeicingRequestPo po = mustFind(requestId);
247	        if (po.getStatus() == RequestStatus.SCHEDULED) {
248	            Instant now = timeSource.now();
249	            requestRepository.updateActualStart(requestId, RequestStatus.IN_PROGRESS, now, now);
250	            allocationRepository.updateStatusByRequest(requestId, RequestStatus.IN_PROGRESS.name());
251	            DeicingRequestPo stored = mustFind(requestId);
252	            List<String> bays = allocationRepository.findByRequestId(requestId).stream()
253	                    .map(DeicingAllocationPo::getBayCode).toList();
254	            return MutationResponse.of(viewMapper.toView(stored), false, bays);
255	        }
256	        if (po.getStatus() == RequestStatus.QUEUED || po.getStatus() == RequestStatus.HOT_RISK) {
257	            throw ApiException.conflict("申请 " + requestId + " 尚未完成出队排定，不能开始作业");
258	        }
259	        return mutationReplay(po);
260	    }
261	
262	    /**
263	     * 实际起飞回报。两步法：恰在 scheduledEnd+HOT 时刻起飞有效，晚于该时刻 HOT 失效，
264	     * 记录进入 HOT_EXPIRED 终态并要求重新除冰。已取消记录不会被复活。
265	     */
266	    @Transactional
267	    public TakeoffResponse reportTakeoff(String requestId, Instant actualTakeoffTime) {
268	        DeicingRequestPo po = mustFind(requestId);
269	
270	        if (po.getStatus() == RequestStatus.CANCELLED) {
271	            // 迟到起飞回报：幂等返回，已取消队列项不得复活
272	            return new TakeoffResponse(viewMapper.toView(po), false, true,
273	                    viewMapper.hotDeadline(po));
274	        }
275	        if (po.getStatus() == RequestStatus.TAKEN_OFF
276	                || po.getStatus() == RequestStatus.HOT_EXPIRED) {
277	            boolean valid = po.getStatus() == RequestStatus.TAKEN_OFF;
278	            return new TakeoffResponse(viewMapper.toView(po), valid, true,
279	                    viewMapper.hotDeadline(po));
280	        }
281	        if (po.getStatus() == RequestStatus.QUEUED || po.getStatus() == RequestStatus.HOT_RISK
282	                || po.getStatus() == RequestStatus.SCHEDULED) {
283	            throw ApiException.conflict("申请 " + requestId
284	                    + " 除冰作业尚未开始/处于 HOT 风险，不得放行起飞");
285	        }
286	        if (po.getScheduledEnd() == null || actualTakeoffTime.isBefore(po.getScheduledEnd())) {
287	            throw ApiException.badRequest("实际起飞时刻早于除冰完成时刻");
288	        }
289	
290	        boolean valid;
291	        RequestStatus nextStatus;
292	        if (po.getType() == DeicingType.TWO_STEP) {
293	            Instant hotDeadline = viewMapper.hotDeadline(po);
294	            // 半开 HOT 区间的对端取等号：恰在 HOT 终点起飞有效
295	            valid = !actualTakeoffTime.isAfter(hotDeadline);
296	            nextStatus = valid ? RequestStatus.TAKEN_OFF : RequestStatus.HOT_EXPIRED;
297	        } else {
298	            valid = true;
299	            nextStatus = RequestStatus.TAKEN_OFF;
300	        }
301	
302	        Instant now = timeSource.now();
303	        requestRepository.updateTakeoffResult(requestId, nextStatus, actualTakeoffTime, now);
304	        allocationRepository.updateStatusByRequest(requestId, nextStatus.name());
305	        DeicingRequestPo stored = mustFind(requestId);
306	        return new TakeoffResponse(viewMapper.toView(stored), valid, false,
307	                viewMapper.hotDeadline(stored));
308	    }
309	
310	    /**
311	     * 取消：释放车位占用，进入 CANCELLED 终态；终态记录上的重复取消幂等成功。
312	     */
313	    @Transactional
314	    public MutationResponse cancel(String requestId) {
315	        DeicingRequestPo po = mustFind(requestId);
316	        if (po.getStatus() == RequestStatus.CANCELLED) {
317	            return mutationReplay(po);
318	        }
319	        if (po.getStatus() == RequestStatus.TAKEN_OFF
320	                || po.getStatus() == RequestStatus.HOT_EXPIRED) {
321	            // 已进入其他终态，取消操作幂等返回但不改变终态
322	            return mutationReplay(po);
323	        }
324	        Instant now = timeSource.now();
325	        requestRepository.updateStatus(requestId, RequestStatus.CANCELLED, now);
326	        allocationRepository.deleteByRequest(requestId);
327	        return mutationReplay(mustFind(requestId));
328	    }
329	
330	    /**
331	     * HOT 风险航班重排起飞时刻：新时刻必须允许在最早可重排时刻之后完成作业，
332	     * 重排后回到排队态等待重新出队。
333	     */
334	    @Transactional
335	    public MutationResponse reschedule(String requestId, Instant newTargetTakeoffTime) {
336	        DeicingRequestPo po = mustFind(requestId);
337	        if (po.getStatus() != RequestStatus.HOT_RISK) {
338	            throw ApiException.conflict("仅 HOT_RISK 状态的记录可重排起飞时刻");
339	        }
340	        Instant now = timeSource.now();
341	        if (!newTargetTakeoffTime.isAfter(now)) {
342	            throw ApiException.badRequest("新起飞时刻必须晚于当前时刻");
343	        }
344	        Instant earliestStart = po.getEarliestReassignTime() == null ? now
345	                : po.getEarliestReassignTime();
346	        Instant earliestCompletion = earliestStart.plusSeconds(po.getDurationMinutes() * 60L);
347	        if (newTargetTakeoffTime.isBefore(earliestCompletion)) {
348	            throw ApiException.conflict("新起飞时刻早于最早可完成时刻 " + earliestCompletion);
349	        }
350	        Instant newDeadline = newTargetTakeoffTime.minusSeconds(po.getDurationMinutes() * 60L);
351	        requestRepository.updateReschedule(requestId, newTargetTakeoffTime, newDeadline, now);
352	        return mutationReplay(mustFind(requestId));
353	    }
354	
355	    /**
356	     * 队列快照：进行中记录在前（按截止时刻、申请序号），终态记录在后，重复查询稳定。
357	     */
358	    @Transactional(readOnly = true)
359	    public SnapshotResponse snapshot() {
360	        List<QueueItemView> items = requestRepository.findAll().stream()
361	                .sorted(snapshotOrder())
362	                .map(po -> viewMapper.toView(po))
363	                .toList();
364	        return new SnapshotResponse(timeSource.now(), items);
365	    }
366	
367	    /**
368	     * 车位占用时间线：按车位与占用起点排序，可复算、重复查询稳定。
369	     */
370	    @Transactional(readOnly = true)
371	    public TimelineResponse timeline() {
372	        Map<String, List<BayTimelineView.OccupancyView>> byBay = new LinkedHashMap<>();
373	        for (DeicingBayPo bay : bayRepository.findActive()) {
374	            byBay.put(bay.getBayCode(), new ArrayList<>());
375	        }
376	        for (DeicingAllocationPo allocation : allocationRepository.findAll()) {
377	            byBay.computeIfAbsent(allocation.getBayCode(), k -> new ArrayList<>())
378	                    .add(viewMapper.toOccupancy(allocation));
379	        }
380	        List<BayTimelineView> bays = byBay.entrySet().stream()
381	                .map(e -> new BayTimelineView(e.getKey(),
382	                        e.getValue().stream()
383	                                .sorted(Comparator.comparing(BayTimelineView.OccupancyView::start)
384	                                        .thenComparing(BayTimelineView.OccupancyView::requestId))
385	                                .toList()))
386	                .toList();
387	        return new TimelineResponse(timeSource.now(), bays);
388	    }
389	
390	    @Transactional(readOnly = true)
391	    public QueueItemView get(String requestId) {
392	        return viewMapper.toView(mustFind(requestId));
393	    }
394	
395	    // ---- 内部辅助 ----------------------------------------------------------
396	
397	    private Integer resolveHot(DeicingType type, String flightNumber) {
398	        if (type == DeicingType.ONE_STEP) {
399	            return null;
400	        }
401	        Integer hot = timetableRepository.findHotMinutes(flightNumber);
402	        if (hot == null || hot <= 0) {
403	            throw ApiException.badRequest("时刻表缺少航班 " + flightNumber
404	                    + " 的两步法防冰液保持时间（HOT）");
405	        }
406	        return hot;
407	    }
408	
409	    private MutationResponse replayOrConflict(DeicingRequestPo existing, String fingerprint) {
410	        if (!existing.getFingerprint().equals(fingerprint)) {
411	            throw ApiException.conflict("requestId " + existing.getRequestId()
412	                    + " 已存在但业务参数不一致，拒绝覆盖");
413	        }
414	        return mutationReplay(existing);
415	    }
416	
417	    private MutationResponse mutationReplay(DeicingRequestPo po) {
418	        List<String> bays = allocationRepository.findByRequestId(po.getRequestId()).stream()
419	                .map(DeicingAllocationPo::getBayCode).toList();
420	        return MutationResponse.of(viewMapper.toView(po), true, bays);
421	    }
422	
423	    private DeicingRequestPo mustFind(String requestId) {
424	        DeicingRequestPo po = requestRepository.findByRequestId(requestId);
425	        if (po == null) {
426	            throw ApiException.notFound("申请不存在: " + requestId);
427	        }
428	        return po;
429	    }
430	
431	    /**
432	     * 在 activeBays 中选择 requiredBays 个车位，使作业能在 earliest 之后最早开始；
433	     * 起点并列时优先共同空闲更久、车位编号更小的组合，保证结果确定。
434	     */
435	    private BaySelection selectBays(List<String> activeBays, Instant earliest, Duration duration,
436	                                    List<DeicingAllocationPo> occupied, int requiredBays) {
437	        record Candidate(String bay, Instant start, Instant end) {
438	        }
439	        Map<String, List<SchedulingCalculator.BayWindow>> windows = new LinkedHashMap<>();
440	        for (String bay : activeBays) {
441	            windows.put(bay, calculator.freeWindows(bay, earliest, duration, occupied));
442	        }
443	
444	        List<Instant> starts = windows.values().stream().flatMap(List::stream)
445	                .map(SchedulingCalculator.BayWindow::windowStart)
446	                .distinct().sorted().toList();
447	
448	        for (Instant start : starts) {
449	            List<Candidate> covering = new ArrayList<>();
450	            for (Map.Entry<String, List<SchedulingCalculator.BayWindow>> entry : windows.entrySet()) {
451	                SchedulingCalculator.BayWindow window = entry.getValue().stream()
452	                        .filter(w -> !start.isBefore(w.windowStart())
453	                                && !start.plus(duration).isAfter(w.windowEnd()))
454	                        .findFirst().orElse(null);
455	                if (window != null) {
456	                    covering.add(new Candidate(entry.getKey(), start, window.windowEnd()));
457	                }
458	            }
459	            if (covering.size() >= requiredBays) {
460	                covering.sort(Comparator.comparing(Candidate::end).reversed()
461	                        .thenComparing(Candidate::bay));
462	                List<String> chosen = covering.subList(0, requiredBays).stream()
463	                        .map(Candidate::bay).sorted().toList();
464	                return new BaySelection(start, chosen);
465	            }
466	        }
467	        return null;
468	    }
469	
470	    private static Comparator<DeicingRequestPo> snapshotOrder() {
471	        return Comparator.comparingInt((DeicingRequestPo po) -> statusGroup(po.getStatus()))
472	                .thenComparing(DeicingRequestPo::getDeadline)
473	                .thenComparingLong(DeicingRequestPo::getSeq);
474	    }
475	
476	    private static int statusGroup(RequestStatus status) {
477	        return switch (status) {
478	            case QUEUED, SCHEDULED, IN_PROGRESS, HOT_RISK -> 0;
479	            case TAKEN_OFF, HOT_EXPIRED, CANCELLED -> 1;
480	        };
481	    }
482	
483	    private record BaySelection(Instant start, List<String> bays) {
484	    }
485	}
